SELECT ca.*, a.description as account_description, a.amount as original_amount, CASE WHEN ca.target_type = 'project' THEN p.project_name WHEN ca.target_type = 'department' THEN d.department_name ELSE 'Unknown' END as target_name FROM cost_allocations ca LEFT JOIN accounts a ON ca.account_record_id = a.account_id LEFT JOIN projects p ON ca.target_type = 'project' AND ca.target_id = p.id LEFT JOIN departments d ON ca.target_type = 'department' AND ca.target_id = d.id WHERE 1=1
AND ca.account_record_id = #{accountRecordId}
AND ca.target_type = #{targetType}
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM cost_allocations ca
WHERE 1=1

    AND ca.account_record_id = #{accountRecordId}


    AND ca.target_type = #{targetType}
